using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Circle.FourNegative.SecondPeakIndependentTailInterior;
internal sealed class FirstEarDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Literal first-ear transport", H("Private proof components consumed by the endpoint"),
        Blocks(Paragraph(Text("The packet strip theorem bounds every take-prefix of each positive-bank/negative-terminal block. The fresh positive label is initially at the end of the first positive bank. first_bank_ear_left moves precisely that label to the front: every prefix of the reordered positive bank is bounded by its unchanged peak, and its sum and entire following suffix remain unchanged. The physical permutation and lift_order then give both full OriginalOrder predicates for one old sigma and literal earWord at cut zero."))), []));
}
